                "Para la gestión de clientes cuenta con numerosos indicadores asistenciales (entre los claves se encuentran Porcentaje de Accesibilidad a Consulta presencial en AP < 24 h, Porcentaje de Cirugía Mayor Ambulatoria, Porcentaje de Participación en el Programa de Cribado de Cáncer Colorrectal,…), indicadores de gestión de la relación con clientes (Tasa de acceso a Carpeta de Salud, reclamaciones, …) y de gestión económico financiera y de recursos (que proporcionan información de gastos y costes actualizados mensualmente y desplegados por servicios y unidades que permiten un seguimiento periódico de los resultados).",
